-- Phase 1 PostgreSQL design; not yet deployed.
-- UUID values are generated by PostgreSQL; passwords and raw photo bytes are never stored here.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 email text NOT NULL UNIQUE,
 role text NOT NULL CHECK (role IN ('homeowner','installer','admin')),
 auth_subject text UNIQUE,
 email_verified_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE projects (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 homeowner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 title varchar(100) NOT NULL,
 description text NOT NULL,
 category text NOT NULL,
 budget_cents bigint CHECK (budget_cents >= 0),
 postal_code varchar(12),
 status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','planning','seeking_quotes','booked','completed','cancelled')),
 created_at timestamptz NOT NULL DEFAULT now(),
 updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX projects_homeowner_idx ON projects(homeowner_id,created_at DESC);
CREATE TABLE project_photos (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
 storage_key text NOT NULL UNIQUE,
 content_type text NOT NULL CHECK(content_type IN ('image/jpeg','image/png','image/webp')),
 byte_size integer NOT NULL CHECK(byte_size > 0 AND byte_size <= 8388608),
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE installer_profiles (
 user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
 business_name text NOT NULL,
 service_area text,
 verification_status text NOT NULL DEFAULT 'pending' CHECK(verification_status IN ('pending','approved','rejected','suspended')),
 created_at timestamptz NOT NULL DEFAULT now()
);
-- All project and photo access MUST be authorized at the API layer.
-- Do not expose this database directly to the browser.
